package com.hau.notification.infrastructure.persistence.adapter;import com.hau.notification.domain.model.Notification;import com.hau.notification.domain.repository.NotificationRepository;import com.hau.notification.infrastructure.persistence.mapper.NotificationPersistenceMapper;import com.hau.notification.infrastructure.persistence.repository.JpaNotificationRepository;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Repository;import java.time.Instant;import java.util.*;@Repository public class NotificationPersistenceAdapter implements NotificationRepository{private final JpaNotificationRepository r;private final NotificationPersistenceMapper m;public NotificationPersistenceAdapter(JpaNotificationRepository r,NotificationPersistenceMapper m){this.r=r;this.m=m;}public Notification save(Notification n){return m.toDomain(r.save(m.toEntity(n)));}public Optional<Notification> findById(UUID id){return r.findById(id).map(m::toDomain);}public List<Notification> findByUser(UUID id,int p,int s){return r.findByUserIdOrderByCreatedAtDesc(id,PageRequest.of(p,s)).stream().map(m::toDomain).toList();}public long countUnread(UUID id){return r.countByUserIdAndReadFalse(id);}public int markAllRead(UUID id,Instant at){return r.markAll(id,at);}}
